package org.marketreview.nativeapp;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
/** Historical research records only; never runs a model or infers a security. */
final class ResearchRuns {
 static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
 static String canonical(Object v)throws Exception{if(v instanceof JSONObject){JSONObject o=(JSONObject)v;List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);List<String> parts=new ArrayList<>();for(String k:keys)parts.add(quote(k)+":"+canonical(o.get(k)));return "{"+String.join(",",parts)+"}";}if(v instanceof JSONArray){List<String> parts=new ArrayList<>();JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)parts.add(canonical(a.get(i)));return "["+String.join(",",parts)+"]";}if(v==null||v==JSONObject.NULL)return "null";if(v instanceof String)return quote((String)v);if(v instanceof Number)return "@"+String.format(Locale.ROOT,"%016x",Double.doubleToLongBits(((Number)v).doubleValue()));return v.toString();}
 static String quote(String s){StringBuilder b=new StringBuilder("\"");for(int i=0;i<s.length();i++){char c=s.charAt(i);switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\b':b.append("\\b");break;case '\f':b.append("\\f");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
 static String fingerprint(Object v)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-256").digest(canonical(v).getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:digest)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 static Object field(JSONObject o,String camel,String snake){return o.has(camel)?o.opt(camel):o.opt(snake);}
 static String text(JSONObject o,String camel,String snake,int max){Object v=field(o,camel,snake);need(v==null||v==JSONObject.NULL||v instanceof String,camel+"必须为文本");String s=v instanceof String?(String)v:"";need(s.length()<=max,camel+"过长，未截断");return s;}
 static Object structured(JSONObject o,String camel,String snake,boolean array)throws Exception{if(!array&&o.has(camel)){Object direct=o.get(camel);return direct==JSONObject.NULL?new JSONObject():direct;}Object v=field(o,camel,snake);if(v==null||v==JSONObject.NULL||"".equals(v))return array?new JSONArray():new JSONObject();if(v instanceof String){JSONTokener t=new JSONTokener((String)v);v=t.nextValue();need(t.nextClean()==0,camel+" JSON含额外内容");}need(!array||v instanceof JSONArray,camel+"结构无效");return v;}
 static JSONObject normalize(JSONObject raw)throws Exception{Object value=raw.opt("id");String id=value instanceof String||value instanceof Number?value.toString():"";need(!id.isEmpty()&&id.length()<=60,"旧运行缺少有效ID");String type=text(raw,"runType","run_type",80),model=text(raw,"modelId","model_id",120),status=text(raw,"status","status",30);need(!type.trim().isEmpty()&&!model.trim().isEmpty(),"运行类型/模型缺失");need(Arrays.asList("pending","completed","failed").contains(status),"旧运行状态无效");String title=text(raw,"title","title",200),result=text(raw,"result","result_text",250000);JSONObject run=new JSONObject().put("id",id).put("runType",type).put("modelId",model).put("status",status).put("title",title).put("question",text(raw,"question","question",2000)).put("prompt",text(raw,"prompt","prompt",250000)).put("result",result).put("evidence",structured(raw,"evidence","evidence_json",true)).put("request",structured(raw,"request","request_json",false)).put("metrics",structured(raw,"metrics","metrics_json",false)).put("createdAt",text(raw,"createdAt","created_at",40)).put("updatedAt",text(raw,"updatedAt","updated_at",40));return new JSONObject().put("id","legacy-research:"+id).put("title",title.isEmpty()?"旧研究运行 #"+id:title).put("text",result).put("verification","unverified").put("legacySource","ai_research_runs").put("legacyOriginal",new JSONObject(raw.toString())).put("researchRun",run).put("sourceFingerprint",fingerprint(raw));}
 static JSONObject content(JSONObject r)throws Exception{JSONObject copy=new JSONObject(r.toString());copy.remove("updatedAt");if(copy.isNull("sourceUrl")||"".equals(copy.opt("sourceUrl")))copy.remove("sourceUrl");return copy;}
 static JSONObject stored(JSONObject r)throws Exception{JSONObject expected=normalize(r.getJSONObject("legacyOriginal"));if(r.has("updatedAt")){need(r.opt("updatedAt") instanceof String,"本机保存时间无效");java.time.Instant.parse(r.getString("updatedAt"));expected.put("updatedAt",r.get("updatedAt"));}if(r.has("sourceUrl")){need(r.isNull("sourceUrl")||"".equals(r.opt("sourceUrl")),"旧研究无顶层来源URL，未接受新增来源");expected.put("sourceUrl",r.get("sourceUrl"));}need(canonical(expected).equals(canonical(r)),"研究备份字段与原记录不一致");return expected;}
 static JSONArray decode(String text)throws Exception{need(text.getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"文件超过32MB，请分批导出");JSONTokener tokener=new JSONTokener(text);Object value=tokener.nextValue();need(tokener.nextClean()==0,"导入JSON含额外内容");JSONArray input;boolean nativeBackup=false;if(value instanceof JSONArray)input=(JSONArray)value;else{need(value instanceof JSONObject,"需要JSON对象或数组");JSONObject o=(JSONObject)value;nativeBackup="native-business-v1".equals(o.optString("schema"));if(nativeBackup)input=o.optJSONArray("reports");else if(o.has("researchRuns"))input=o.optJSONArray("researchRuns");else{JSONObject tables=o.optJSONObject("tables");input=tables==null?null:tables.optJSONArray("researchRuns");}need(input!=null,"备份缺少researchRuns或tables.researchRuns研究数组");}need(input.length()<=10000,"运行记录超过10000条，请分批导出");JSONArray out=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<input.length();i++){JSONObject raw=input.getJSONObject(i);if(nativeBackup){if(!"ai_research_runs".equals(raw.optString("legacySource")))continue;stored(raw);}else raw=normalize(raw);need(seen.add(raw.getString("id")),"同一文件重复运行ID："+raw.getString("id"));out.put(raw);}return out;}
 static JSONObject preview(JSONArray incoming,JSONArray current)throws Exception{JSONArray insert=new JSONArray(),conflicts=new JSONArray();int duplicates=0;Map<String,JSONObject> previous=new HashMap<>();for(int i=0;i<current.length();i++)previous.put(current.getJSONObject(i).getString("id"),current.getJSONObject(i));for(int i=0;i<incoming.length();i++){JSONObject r=incoming.getJSONObject(i),old=previous.get(r.getString("id"));if(old==null)insert.put(r);else if(canonical(content(old)).equals(canonical(content(r))))duplicates++;else conflicts.put(r.getString("id"));}return new JSONObject().put("incoming",incoming).put("insert",insert).put("duplicates",duplicates).put("conflicts",conflicts).put("baseline",fingerprint(current));}
 static JSONArray filter(JSONArray all,String type,String status,String model,String query)throws Exception{List<JSONObject> rows=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(!"ai_research_runs".equals(r.optString("legacySource")))continue;JSONObject run=r.getJSONObject("researchRun");if(!type.isEmpty()&&!type.equals(run.optString("runType"))||!status.isEmpty()&&!status.equals(run.optString("status"))||!model.isEmpty()&&!model.equals(run.optString("modelId")))continue;if(!(run.optString("title")+" "+run.optString("question")+" "+run.optString("id")).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;rows.add(r);}rows.sort((a,b)->{JSONObject ar=a.optJSONObject("researchRun"),br=b.optJSONObject("researchRun");int c=br.optString("createdAt").compareTo(ar.optString("createdAt"));if(c!=0)return c;try{return Long.compare(Long.parseLong(br.optString("id")),Long.parseLong(ar.optString("id")));}catch(NumberFormatException e){return br.optString("id").compareTo(ar.optString("id"));}});JSONArray out=new JSONArray();for(JSONObject r:rows)out.put(r);return out;}
 static JSONObject backup(JSONArray reports)throws Exception{JSONObject b=new JSONObject().put("schema","native-business-v1").put("mergePolicy","keep-existing");for(String k:new String[]{"accounts","trades","docs","topics","relations","collections"})b.put(k,new JSONArray());b.put("reports",filter(reports,"","","",""));return b;}
 static String pretty(Object v)throws Exception{return v instanceof JSONObject?((JSONObject)v).toString(2):v instanceof JSONArray?((JSONArray)v).toString(2):String.valueOf(v);}
 static String read(JSONObject r)throws Exception{JSONObject run=r.getJSONObject("researchRun");String result=run.optString("result");if(result.isEmpty())result="pending".equals(run.optString("status"))?"旧运行未结束，未恢复调用":"原记录未保存结果";return "历史记录 · 原状态："+run.optString("status")+"\n类型："+run.optString("runType")+" · 历史模型："+run.optString("modelId")+"\n创建："+run.optString("createdAt")+" · 更新："+run.optString("updatedAt")+"\n原记录规范指纹 SHA256："+r.optString("sourceFingerprint")+"\n\n问题\n"+run.optString("question")+"\n\n完整报告\n"+result+"\n\n完整提示词\n"+run.optString("prompt")+"\n\n完整证据\n"+run.getJSONArray("evidence").toString(2)+"\n请求原文\n"+pretty(run.get("request"))+"\n指标 / 失败原文\n"+pretty(run.get("metrics"))+"\n完整旧记录\n"+r.getJSONObject("legacyOriginal").toString(2);}
}
